 "content": "def transform(grid):
    # Fill each hollow frame's interior: small square holes use 7 for 1x1,
    # 2x2 interiors use 2, and the tall/wide large frame uses 7.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            y0=min(y for y,x in cells); y1=max(y for y,x in cells)
            x0=min(x for y,x in cells); x1=max(x for y,x in cells)
            ih,iw=y1-y0-1,x1-x0-1
            if ih<=0 or iw<=0: continue
            # Frames with dimensions 4x4 have 2x2 holes, filled with 2;
            # the 3x3 frame's single-cell hole is 7; large 5x7 frame is 7.
            fill=2 if (ih,iw)==(2,2) else 7
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    if grid[y][x]==bg: out[y][x]=fill
    return out
